 5	const grid = document.querySelector('#grid');
 6	const body = grid.querySelector('tbody');
 7	
 8	let draftRevision = 0;
 9	
10	input.addEventListener('input', () => {
11	  draftRevision += 1;
12	});
13	
14	clear.addEventListener('click', () => {
15	  if (input.value !== '') {
16	    input.value = '';
17	    draftRevision += 1;
18	  }
19	  input.focus();
20	});
21	
22	save.addEventListener('click', async () => {
23	  const submittedValue = input.value;
24	  const submittedRevision = draftRevision;
25	
26	  save.disabled = true;
27	  feedback.textContent = 'Saving';
28	
29	  try {
30	    const response = await fetch('/save', { method: 'POST', body: submittedValue });
31	    if (!response.ok) throw new Error('Save failed');
32	
33	    body.rows[0].cells[0].textContent = submittedValue;
34	    feedback.textContent = 'Saved';
35	
36	    // A completed save only consumes the draft it actually submitted.
37	    if (draftRevision === submittedRevision) {
38	      input.value = '';
39	      draftRevision += 1;
40	    }
41	  } catch {
42	    feedback.textContent = 'Save failed';
43	  } finally {
44	    save.disabled = false;
45	  }
46	});
47	
48	for (let index = 0; index < 30; index += 1) {
49	  const row = body.insertRow();
50	  row.dataset.row = String(index);
51	  row.insertCell().textContent = `Record ${index}`;
52	}
53	
54	function animateVisibleRows() {
55	  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
56	
57	  const clip = grid.getBoundingClientRect();
58	  const visibleRows = [...body.rows].filter((row) => {
59	    const bounds = row.getBoundingClientRect();
60	    return bounds.bottom > clip.top && bounds.top < clip.bottom;
61	  });
62	
63	  for (const row of visibleRows) {
64	    row.animate(
65	      [
66	        { opacity: 0, transform: 'translateY(4px)' },
67	        { opacity: 1, transform: 'translateY(0)' },
68	      ],
69	      { duration: 240, easing: 'ease-out' },
70	    );
71	  }
72	}
73	
74	const readyDelay = Number(new URLSearchParams(location.search).get('delay') || 200);
75	setTimeout(() => {
76	  grid.dataset.ready = 'true';
77	  requestAnimationFrame(animateVisibleRows);
78	}, readyDelay);
